style.css:
@-moz-document domain("scpfoundation.net"), domain("scpfoundation.ru"), domain("scp-ru.wikidot.com") {
/* ============================================================
     BASE

     Articles may ship their own <style> block, which the browser sees AFTER
     this sheet — equal specificity there loses. Article-body rules therefore
     carry !important, and the ones an article theme is most likely to claim
     are written with two ids so an author's inline colour still wins.
     ============================================================ */

  /* Headings and links state a colour directly on the element, so they cannot
     reach an author's callout box by inheritance the way body ink does. They
     read these instead, and a light author box rebinds them for its subtree. */
  :root {
    color-scheme: dark;
    --scpru-title: #e05f6b;
    --scpru-heading: #e6edf3;
    --scpru-link: #e8626e;
    --scpru-link-visited: #cf90a8;
    --scpru-link-hover: #ff8f97;
    --scpru-lift-black: #c4cdd6;
    --scpru-lift-blue: #79c0ff;
    --scpru-lift-green: #7ee787;
    --scpru-lift-purple: #d2a8ff;
    --scpru-lift-maroon: #ff9492;
    --scpru-lift-red: #ff453a;
    --scpru-lift-brown: #d4a373;
    --scpru-lift-teal: #56d4dd;

    /* The 2023 sidebar redesign draws its corner brackets, its folded-section
       wipe and its section rules from one crimson. */
    --new-side-bar-color: #8a2f2f;
  }

  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  #html-body,
  #skrollr-body,
  #container-wrap-wrap,
  #container,
  #content-wrap,
  #main-content,
  #page-content,
  #action-area {
    background-color: transparent;
  }

  /* The masthead art is a black-to-maroon band with a mid-grey stripe at
     140-165px (the top menu) and nothing below it — the PNG is transparent
     there, so only that stripe has to be repainted. A first background layer
     covers it; the artwork stays as the second layer and keeps the identity.
     The artwork URL must stay absolute: userstyles.org rejects any relative
     url() reference at upload. */
  div#container-wrap {
    background-color: #14181d !important;
    background-image:
      linear-gradient(transparent 140px, #1c2128 140px, #1c2128 165px, transparent 165px),
      url("https://scpfoundation.net/-/static/images/scp-bg.png") !important;
    background-repeat: repeat-x, repeat-x !important;
    background-position: top left, top left !important;
  }

  /* iframes default to a 2px inset border in currentColor, which turns light
     the moment the page text does. */
  iframe {
    border-color: #2d333b;
  }

  hr {
    color: #2d333b !important;
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }

  /* The front page's own divider carries a light drop shadow. */
  .hr-main {
    background-color: #3a4048 !important;
    box-shadow: 0 2px 3px rgba(0, 0, 0, .5) !important;
  }

  /* ============================================================
     TYPOGRAPHY
     ============================================================ */

  /* Site chrome — always on the page floor, so the colour is pinned. */
  #page-title,
  .meta-title,
  .sub-page-title,
  .sub-page-title h1 {
    color: var(--scpru-title) !important;
    border-color: #2d333b !important;
  }

  /* An in-article h1 is not pinned: an article that states a heading colour has
     a surface of its own in mind for it, and this only has to beat the site's
     base #901, which document order already does. Pinning it strips the light
     ink off headings on author-painted dark panels. */
  h1 {
    color: var(--scpru-title);
    border-color: #2d333b;
  }

  h2,
  h3,
  h4,
  h5,
  h6 {
    color: var(--scpru-heading);
  }

  /* Declared on the article root ONLY, so the ink reaches the text by
     inheritance. A copy of this on p/li/dd/dt/td is a direct declaration and
     beats any colour an author put on a wrapping callout box, however specific
     or inline that wrapper's colour was — which erases the author's ink while
     leaving their light paper behind. */
  #page-content,
  .thread-container .post .content,
  .forum-thread-box .description-block {
    color: #c4cdd6;
  }

  /* Authors build callout boxes as [[div style="background:#EEE"]] and let the
     site's near-black body ink carry the words — the wrapper names a paper
     colour and no ink. That paper survives the theme, so the box has to hand
     the ink back. Matched on the VALUE (an inline background alongside a light
     hex or `white`), never on a class: the classes are page-local and differ
     per article.
     The `white` keyword is matched only where a background PROPERTY precedes
     it, because a malformed author style — `background: #white` — names no
     colour at all, paints nothing, and would take the dark ink onto the page
     floor. The hex forms stay loose so a gradient stop still matches.
     The saturated colour KEYWORDS listed last are the ones whose luminance
     carries near-black ink better than light ink — `red` reads at 5.3:1 dark
     and 2.5:1 light. `blue`, `navy`, `purple` and `maroon` are deliberately
     absent for the same reason in reverse, and the `dark` guard keeps their
     `darkred`/`darkorange` relatives out of the list.
     Deliberately NOT !important — an author who did name their own colour
     still wins, so this can never read worse than the unstyled site. */
  #page-content [style*="background"][style*="#c"],
  #page-content [style*="background"][style*="#d"],
  #page-content [style*="background"][style*="#e"],
  #page-content [style*="background"][style*="#f"],
  #page-content [style*="background"][style*="#C"],
  #page-content [style*="background"][style*="#D"],
  #page-content [style*="background"][style*="#E"],
  #page-content [style*="background"][style*="#F"],
  #page-content [style*="background:white"],
  #page-content [style*="background: white"],
  #page-content [style*="background-color:white"],
  #page-content [style*="background-color: white"],
  #page-content [style*="background"][style*="red"]:not([style*="dark"]),
  #page-content [style*="background"][style*="yellow"]:not([style*="dark"]),
  #page-content [style*="background"][style*="orange"]:not([style*="dark"]),
  #page-content [style*="background"][style*="gold"]:not([style*="dark"]),
  #page-content [style*="background"][style*="lime"]:not([style*="dark"]),
  #page-content [style*="background"][style*="aqua"]:not([style*="dark"]),
  #page-content [style*="background"][style*="cyan"]:not([style*="dark"]),
  #page-content [style*="background"][style*="pink"]:not([style*="dark"]),
  #page-content [style*="background"][style*="magenta"]:not([style*="dark"]) {
    color: #140f0c;
    --scpru-title: #7a1d24;
    --scpru-heading: #140f0c;
    --scpru-link: #a4161a;
    --scpru-link-visited: #6d3550;
    --scpru-link-hover: #d21414;
    /* On paper the author's own dark end of the ##blue|…## palette reads, and
       the lifted end does not. */
    --scpru-lift-black: #140f0c;
    --scpru-lift-blue: #0000cd;
    --scpru-lift-green: #046307;
    --scpru-lift-purple: #800080;
    --scpru-lift-maroon: #800000;
    --scpru-lift-red: #c30000;
    --scpru-lift-brown: #6b4423;
    --scpru-lift-teal: #006a6a;
  }

  /* ============================================================
     LINKS — the crimson identity, lifted for dark
     ============================================================ */

  a,
  #interwiki a,
  #side-bar a,
  #side-bar a:visited,
  #page-content a {
    color: var(--scpru-link);
  }

  a:visited,
  #page-content a:visited {
    color: var(--scpru-link-visited);
  }

  a:hover,
  #page-content a:hover {
    color: var(--scpru-link-hover);
  }

  /* Article themes reach the body links from their own page-scoped rules, which
     out-specify a single-id selector — on the themes that pitch their links
     near-black for a light page, that leaves them invisible here. Two ids win
     on the id count alone, so no !important is needed and an author's inline
     colour (and the ##name|text## lifts further down) still take precedence. */
  #main-content #page-content a {
    color: var(--scpru-link);
  }

  #main-content #page-content a:visited {
    color: var(--scpru-link-visited);
  }

  #main-content #page-content a:hover {
    color: var(--scpru-link-hover);
  }

  /* Wikidot paints a light hover fill on every link. Kept at low specificity
     so component rules (the rating buttons) can still fill their own hover. */
  a:hover {
    background-color: transparent !important;
  }

  a.newpage,
  a.newpage:visited,
  #main-content #page-content a.newpage,
  #main-content #page-content a.newpage:visited {
    color: #e8944a;
  }

  #page-content a.collapsible-block-link {
    color: var(--scpru-link);
  }

  /* ============================================================
     MASTHEAD / TOP BAR / SEARCH
     ============================================================ */

  #header h1 a {
    color: #eee;
  }

  #header h2 span {
    color: #f0f0c0;
  }

  /* Article themes hide the masthead's real text with `color: transparent` and
     draw their own copy from a pseudo-element, pitched near-black for a light
     bar. Only the pseudo is coloured: touching the anchor itself would print a
     second title over the first on every theme that does this.
     `color` alone is taken — a theme whose title is knocked-out artwork sets
     -webkit-text-fill-color to transparent so the artwork shows through the
     glyphs, and naming it here would paint over that artwork. */
  #header h1 a::before,
  #header h1 a::after {
    color: #eee !important;
  }

  #header h2::before,
  #header h2::after,
  #header h2 span::before,
  #header h2 span::after {
    color: #f0f0c0 !important;
  }

  #login-status {
    color: #9aa4ae !important;
  }

  #login-status a,
  #login-status a.btn,
  #login-status a.btn-primary {
    background-color: transparent !important;
    border-color: transparent !important;
    color: #dde3e9 !important;
  }

  #login-status a:hover {
    color: #ff8f97 !important;
  }

  #login-status ul a,
  #account-options li a {
    color: #e8626e !important;
  }

  #account-options {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .6);
  }

  #account-options li a:hover {
    color: #ff8f97 !important;
    background-color: #262c33 !important;
  }

  #account-topbutton {
    background-color: #2d333b !important;
    color: #e8626e !important;
    border-color: #3a4048 !important;
  }

  #top-bar a {
    color: #eaeaea !important;
  }

  /* The dropdown panel carries its own border and shadow; the anchor fills
     below only cover the rows, not the gaps between them. */
  #top-bar ul li ul {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    box-shadow: 0 4px 12px rgba(0, 0, 0, .7);
  }

  /* Only the left and right sides are drawn. Stating all four keeps the two at
     zero width off currentColor, which is now light. */
  #top-bar ul li a {
    border-color: rgba(255, 255, 255, .06) !important;
  }

  /* Open dropdown: the site paints these #eee / #fff */
  #top-bar ul li.sfhover a,
  #top-bar ul li:hover a,
  #top-bar li ul li a,
  #top-bar a:hover {
    background-color: #1c2128 !important;
    color: #ff8f97 !important;
    border-left-color: #3a4048 !important;
    border-right-color: #3a4048 !important;
  }

  #top-bar ul li.sfhover a:hover,
  #top-bar ul li:hover a:hover {
    background-color: #262c33 !important;
  }

  #top-bar ul li.sfhover ul li a,
  #top-bar ul li:hover ul li a {
    border-top-color: #2d333b !important;
  }

  #top-bar ul li ul a {
    color: #ff8f97;
  }

  /* Mobile hamburger — a white disc with a grey rule and a grey glyph. */
  #top-bar .open-menu a {
    background-color: #1c2128 !important;
    border-color: #4a5058 !important;
    color: #eaeaea !important;
    -webkit-text-fill-color: #eaeaea !important;
  }

  #top-bar .open-menu a:hover {
    box-shadow: 0 0 16px 2px rgba(0, 0, 0, .8) !important;
  }

  #top-bar .mobile-top-bar {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #3a4048 !important;
  }

  /* The glyph is the anchor's own "≡" character, and an article theme can hold
     its `color` at a near-black pitched for its light bar that no specificity
     dislodges. -webkit-text-fill-color is what actually paints the glyph. */
  #top-bar .mobile-top-bar a {
    color: #eaeaea !important;
    -webkit-text-fill-color: #eaeaea !important;
  }

  /* The search field and its button already sit on the site's own dark maroon,
     so only the ink and the light focus outline are re-pitched.
     Article themes repaint this input white with black ink from a rule of the
     same single-id weight, and theirs is later in the document, so the second
     id is what decides it. */
  #header #search-top-box-input,
  #header #search-top-box input.text {
    background-color: #22181a !important;
    color: #e6edf3 !important;
    border-color: #6d4a4a !important;
  }

  #header #search-top-box-input:hover,
  #header #search-top-box-input:focus {
    background-color: #33272a !important;
    border-color: #b98a8a !important;
    color: #fff !important;
  }

  #search-top-box input.empty {
    color: #a08a8a !important;
  }

  #search-top-box-form input[type="submit"] {
    background-color: #5a2f2f !important;
    background-image: linear-gradient(to bottom, #7d4444, #5a2f2f, #33272a) !important;
    border-color: #6d4a4a !important;
    color: #e8d8d8 !important;
  }

  #search-top-box-form input[type="submit"]:hover,
  #search-top-box-form input[type="submit"]:focus {
    background-color: #7d4444 !important;
    background-image: linear-gradient(to bottom, #a06666, #7d4444, #5a2f2f) !important;
    border-color: #b98a8a !important;
    color: #fff !important;
  }

  /* ============================================================
     SIDE BAR
     ============================================================ */

  /* Every rule that names a sidebar SURFACE carries the wrapper id as well.
     Article themes repaint these blocks white from `#side-bar .side-block`
     with !important — the same weight as ours, and later in the document, so
     nothing but a second id decides it. The `#interwiki` half lives in a
     separate frame document that has no wrapper and is never contested. */
  #container-wrap #side-bar {
    background-color: #14181d !important;
    border-color: #2d333b !important;
  }

  #container-wrap #side-bar .side-block,
  #container-wrap #side-bar #u-side-footer,
  #interwiki .side-block {
    background-color: #1c2128 !important;
    border-color: #7d3030 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .55) !important;
  }

  /* The site tints two panels — keep those hues, at dark-surface lightness */
  #container-wrap #side-bar .side-block.media,
  #interwiki .side-block.media {
    background-color: #1e2133 !important;
  }

  #container-wrap #side-bar .side-block.resources,
  #interwiki .side-block.resources {
    background-color: #2a1c1c !important;
  }

  #container-wrap #side-bar .heading,
  #interwiki .heading {
    color: #e07b83 !important;
    border-bottom-color: #7d3030 !important;
  }

  /* The sidebar's own ink. Article themes state `#side-bar a` near-black for
     the white blocks they paint, and once the block above is ours instead, the
     ink has to come with the surface — so every rule in this group carries the
     wrapper id too, and the component rules below carry it as well so the two
     ids do not steal their labels. */
  #container-wrap #side-bar a,
  #container-wrap #side-bar a:visited,
  #interwiki a {
    color: var(--scpru-link) !important;
  }

  #container-wrap #side-bar a:hover,
  #interwiki a:hover {
    color: var(--scpru-link-hover) !important;
  }

  #container-wrap #side-bar .menu-item.inactive a,
  #interwiki .menu-item.inactive a {
    color: #7d858e !important;
  }

  #side-bar .menu-item .sub-text,
  #interwiki .menu-item .sub-text {
    color: #8b949e !important;
  }

  /* The row separator carries no colour of its own, so it takes the link/body
     ink — a bright hairline under every entry once that ink is light. */
  #side-bar .menu-item,
  #interwiki .menu-item {
    border-color: #2d333b !important;
  }

  /* --- the 2023 sidebar redesign --- */

  #container-wrap #side-bar .new-side-block {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  #container-wrap #side-bar .new-heading {
    color: #e07b83 !important;
    border-top-color: #7d3030 !important;
  }

  #container-wrap #side-bar .new-side-block h6 a {
    color: #c4cdd6 !important;
  }

  /* "Случайная статья" / "Поиск по тегам" — a near-white gradient plate with
     grey uppercase labels, and a crimson gradient under the cursor. */
  #container-wrap #side-bar .random-article-block {
    background: linear-gradient(to top, #1c2128 0%, #1c2128 80%, #262c33 100%) !important;
    border-color: #3a4048 !important;
    box-shadow: 0 2px 3px rgba(0, 0, 0, .5) !important;
  }

  #container-wrap #side-bar .random-article-block .menu-item:first-child {
    border-bottom-color: #3a4048 !important;
  }

  #container-wrap #side-bar .random-article-block > .menu-item a {
    color: #c4cdd6 !important;
  }

  #container-wrap #side-bar .random-article-block .menu-item:first-child:hover,
  #container-wrap #side-bar .random-article-block .menu-item:last-child:hover {
    background: linear-gradient(to top, #7d3030 0%, #7d3030 80%, #a03636 100%) !important;
  }

  #container-wrap #side-bar .random-article-block > .menu-item:hover a {
    color: #fff !important;
  }

  /* "Об организации" and its siblings. Folded, the block is a half-crimson,
     half-WHITE gradient that slides across on hover — only the white half is
     restated, so the wipe still reads as a wipe. */
  #container-wrap #side-bar .collapsible-side .collapsible-block-folded {
    background: linear-gradient(to left, #1c2128 50%, var(--new-side-bar-color) 50%) right !important;
    background-size: 200% 100% !important;
  }

  #container-wrap #side-bar .collapsible-side .collapsible-block-folded:hover {
    background-position: left !important;
  }

  #container-wrap #side-bar .collapsible-block-link {
    color: #e07b83 !important;
  }

  #container-wrap #side-bar .collapsible-side .collapsible-block-folded:hover .collapsible-block-link,
  #container-wrap #side-bar .collapsible-side .collapsible-block-unfolded-link a {
    color: #fff !important;
  }

  #side-bar .collapsible-block-unfolded-link {
    border-color: #7d3030 !important;
  }

  /* Mobile slide-out drawer. Below 768px the site fills it dusty rose. */
  @media (max-width: 767px) {
    #container-wrap #side-bar {
      background-color: #0d1117 !important;
    }

    #side-bar:target .close-menu {
      background: rgba(0, 0, 0, .6) !important;
    }
  }

  /* ============================================================
     TABLES
     ============================================================ */

  /* No ink here: td would beat an author box's inherited colour the same way
     the page-content copy did. The cell text inherits; th states its own. */
  table.wiki-content-table td,
  table.wiki-content-table th {
    border-color: #2d333b !important;
  }

  table.wiki-content-table th {
    background-color: #22282f !important;
    color: #e6edf3 !important;
  }

  table.page-compare td,
  table.page-compare th,
  table.form.grid td,
  table.form.grid th,
  .gallery-item,
  table.page-history td.optionstd a {
    border-color: #2d333b !important;
  }

  .alternate:nth-child(2n) {
    background-color: rgba(255, 255, 255, .04) !important;
  }

  table.page-files .highlight {
    background-color: #22282f !important;
  }

  /* ============================================================
     CODE / TOC / NOTES / QUOTES
     ============================================================ */

  /* An element that names its own paper inline is left as authored — these
     fills are !important and would otherwise strip the author's box down to
     our surface while the ink rebind above hands its contents a DARK colour,
     leaving the text on the page floor at no contrast at all. */
  .code:not([style*="background"]),
  #toc:not([style*="background"]),
  .page-source:not([style*="background"]),
  div.note:not([style*="background"]) {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  div.note-block:not([style*="background"]) {
    border-color: #7d3030 !important;
    background-color: #1a1f26 !important;
  }

  blockquote:not([style*="background"]),
  div.blockquote:not([style*="background"]) {
    background-color: #1a1f26 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6;
  }

  /* Wikidot's own syntax palette */
  .hl-default,
  .hl-code,
  .hl-brackets,
  .hl-identifier,
  .hl-main {
    color: #c9d1d9 !important;
  }

  .hl-comment {
    color: #8b949e !important;
  }

  .hl-quotes,
  .hl-string {
    color: #a5d6ff !important;
  }

  .hl-reserved {
    color: #ff7b72 !important;
  }

  .hl-var {
    color: #79c0ff !important;
  }

  .hl-inlinetags {
    color: #d2a8ff !important;
  }

  .hl-gutter {
    background-color: #22282f !important;
    color: #8b949e !important;
  }

  /* highlight.js, which the site ships in its GitHub LIGHT theme */
  .hljs {
    background-color: #1a1f26 !important;
    color: #c9d1d9 !important;
  }

  .hljs-doctag,
  .hljs-keyword,
  .hljs-meta .hljs-keyword,
  .hljs-template-tag,
  .hljs-template-variable,
  .hljs-type,
  .hljs-variable.language_ {
    color: #ff7b72 !important;
  }

  .hljs-title,
  .hljs-title.class_,
  .hljs-title.class_.inherited__,
  .hljs-title.function_ {
    color: #d2a8ff !important;
  }

  .hljs-attr,
  .hljs-attribute,
  .hljs-literal,
  .hljs-meta,
  .hljs-number,
  .hljs-operator,
  .hljs-variable,
  .hljs-selector-attr,
  .hljs-selector-class,
  .hljs-selector-id {
    color: #79c0ff !important;
  }

  .hljs-regexp,
  .hljs-string,
  .hljs-meta .hljs-string {
    color: #a5d6ff !important;
  }

  .hljs-built_in,
  .hljs-symbol {
    color: #ffa657 !important;
  }

  .hljs-comment,
  .hljs-code,
  .hljs-formula {
    color: #8b949e !important;
  }

  .hljs-name,
  .hljs-quote,
  .hljs-selector-tag,
  .hljs-selector-pseudo {
    color: #7ee787 !important;
  }

  .hljs-subst,
  .hljs-emphasis,
  .hljs-strong {
