  .gsc-results,
  .gsc-webResult,
  .gsc-result,
  .gsc-above-wrapper-area,
  .gsc-adBlock,
  .gsc-table-result,
  .gsc-thumbnail-inside,
  .gsc-url-top,
  .gsc-cursor-box {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }

  .gsc-input-box,
  .gsc-completion-container,
  .gssb_c .gssb_e {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  .gsc-input,
  .gsc-input-box input,
  .gsib_a,
  .gsib_b {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  .gsc-search-button,
  .gsc-search-button-v2 {
    background-color: #8a2f2f !important;
    border-color: #8a2f2f !important;
  }

  .gsc-search-button-v2:hover {
    background-color: #a03636 !important;
    border-color: #a03636 !important;
  }

  /* The embed's configured link red is #d52c1f, stated !important from a
     two-class rule that reaches the anchor and every element inside it. Three
     classes are what it takes to out-specify; the hue is kept and lifted. */
  .gsc-control-cse .gs-result .gs-title,
  .gsc-control-cse .gs-result .gs-title *,
  .gsc-control-cse .gs-per-result-labels a.gs-label,
  .gsc-control-cse .gsc-cursor-page,
  .gsc-control-cse .gcsc-find-more-on-google-text,
  .gsc-control-cse .gcsc-find-more-on-google-query {
    color: #e8626e !important;
  }

  .gsc-control-cse .gs-result a.gs-title:hover,
  .gsc-control-cse .gs-result a.gs-title:hover *,
  .gsc-control-cse .gsc-cursor-page:hover,
  .gsc-control-cse .gsc-cursor-current-page {
    color: #ff8f97 !important;
  }

  .gs-snippet,
  .gs-snippet b,
  .gsc-option,
  .gsc-option-menu-item {
    color: #c4cdd6 !important;
  }

  /* Google's result URL green sits at 3.3:1 on the dark page; same hue, lifted. */
  .gs-visibleUrl,
  .gs-visibleUrl-short,
  .gs-visibleUrl-long,
  .gs-visibleUrl-breadcrumb,
  .gs-visibleUrl span {
    color: #7ee787 !important;
  }

  .gsc-result-info,
  .gsc-orderby-label,
  .gsc-clear-button,
  .gs-fileFormat,
  .gs-fileFormatType,
  .gcsc-find-more-on-google {
    color: #8b949e !important;
  }

  .gsc-tabHeader {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .gsc-tabHeader.gsc-tabhActive {
    background-color: #22282f !important;
    border-bottom-color: #8a2f2f !important;
    color: #e6edf3 !important;
  }

  .gsc-option-menu-container,
  .gsc-selected-option-container {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  .gsc-option-menu-item-highlighted,
  .gsc-webResult.gsc-result:hover {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .gsc-webResult-divider {
    border-color: #2d333b !important;
  }

  /* Each pager digit carries its own white plate. */
  .gsc-control-cse .gsc-cursor-page {
    background-color: transparent !important;
  }

  /* ============================================================
     SYSTEM PAGES — login, join, profile, preferences

     A separate `body.system` layout with its own token set. The tokens are
     declared on :root by a stylesheet only these pages load; they are rebound
     on the body instead, so a page that never loads that sheet is untouched.
     ============================================================ */

  body.system {
    --background-color: #14181d;
    --input-background: #1c2128;
    --icon-color: #8b949e;
    --hover-color: #ff8f97;
    --btn-background: #262c33;
    --btn-color: #e6edf3;
    --under-text-color: #8b949e;
    --error-color: #f08a8a;
    --error-border: #6d3436;
    --error-background: #2a1618;
  }

  .system-container {
    background-color: #0d1117 !important;
  }

  .system-content {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    box-shadow:
      0 0 0 1px #2d333b inset,
      2px 2px 8px rgba(0, 0, 0, .6) !important;
    color: #c4cdd6 !important;
  }

  /* The heading band is already a black-to-teal gradient; its pinstripe overlay
     is a white one, which only lifts the band on a dark page. */
  .system-content .heading {
    background-image:
      repeating-linear-gradient(45deg, rgba(0, 0, 0, .14), transparent 4px),
      linear-gradient(to bottom, #000, #23383a) !important;
  }

  .system-content .error {
    background-color: #2a1618 !important;
    border-color: #6d3436 !important;
    color: #f08a8a !important;
  }

  .system-message {
    background-color: #22282f !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  .system-message.success {
    background-color: #14251a !important;
    border-color: #2c5c36 !important;
    color: #7ee787 !important;
  }

  .system-message.error {
    background-color: #2a1618 !important;
    border-color: #6d3436 !important;
    color: #f08a8a !important;
  }

  .system-content .content input[type="text"],
  .system-content .content input[type="password"],
  .system-content .content input[type="email"],
  .system-content .content textarea,
  .system-content .content .profile-mod-until input[type="datetime-local"],
  .system-content .content .profile-public-field input[type="file"],
  .system-content .content .profile-public-field select,
  .preferences-form select {
    background-color: #14181d !important;
    border-color: #4a5058 !important;
    color: #e6edf3 !important;
  }

  .system-content .content button,
  .system-content .content input[type="submit"] {
    background-color: #2a3c3c !important;
    color: #e6edf3 !important;
  }

  .system-content .content button:hover,
  .system-content .content input[type="submit"]:hover {
    background-color: #3d5757 !important;
  }

  .system-content .content button:active,
  .system-content .content input[type="submit"]:active {
    background-color: #16211f !important;
    color: #6fb6b6 !important;
  }

  .system-content .profile-actions a,
  .profile-notices p,
  .profile-mod-section,
  .preferences-sidebar {
    background-color: #22282f !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  .system-content .profile-actions a:hover {
    background-color: #333a42 !important;
    color: #fff !important;
  }

  .profile-details dt,
  .profile-mod-until,
  .profile-mod-choice small,
  .profile-public-field small,
  .preferences-form .helptext {
    color: #8b949e !important;
  }

  .profile-mod-panel {
    border-top-color: #3a4048 !important;
  }

  .profile-mod-panel.is-locked {
    background-color: #2a2313 !important;
    border-color: #6d5a2a !important;
    color: #e0c07a !important;
  }

  .profile-mod-header a,
  .profile-mod-section summary,
  .profile-mod-grid legend,
  .profile-public-field label,
  .preferences-sections a,
  .preferences-form label {
    color: #e6edf3 !important;
  }

  .preferences-sections a:hover {
    color: #ff8f97 !important;
  }

  .profile-mod-grid fieldset {
    background-color: #1a1f26 !important;
    border-color: #3a4048 !important;
  }

  .profile-mod-choice,
  .system-content .content form .profile-mod-choice {
    background-color: #1a1f26 !important;
    border-color: #3a4048 !important;
  }

  .preferences-form .errorlist,
  .profile-form-errors,
  .profile-mod-section .errorlist {
    color: #f08a8a !important;
  }

  a.manage-user:hover {
    color: #ff8f97 !important;
  }

  /* ============================================================
     AUTHOR-WRITTEN INLINE COLOURS

     Wiki syntax like ##blue|text## emits a literal inline `color:`. The dark
     end of that palette is unreadable on a dark page, so lift the common names
     and hexes to the same hue at a legible lightness. Every selector is
     guarded against `background-color: red`, which contains the substring
     `color:red` — unguarded, a span that named only a FILL has its ink
     repainted the same hue and vanishes.
     ============================================================ */

  #page-content [style*="color:black"]:not([style*="background"]),
  #page-content [style*="color: black"]:not([style*="background"]),
  #page-content [style*="color:#000"]:not([style*="background"]),
  #page-content [style*="color: #000"]:not([style*="background"]) {
    color: var(--scpru-lift-black) !important;
  }

  #page-content [style*="color:blue"]:not([style*="background"]),
  #page-content [style*="color: blue"]:not([style*="background"]),
  #page-content [style*="color:navy"]:not([style*="background"]),
  #page-content [style*="color: navy"]:not([style*="background"]),
  #page-content [style*="color:#0000ff"]:not([style*="background"]),
  #page-content [style*="color: #0000ff"]:not([style*="background"]) {
    color: var(--scpru-lift-blue) !important;
  }

  #page-content [style*="color:green"]:not([style*="background"]),
  #page-content [style*="color: green"]:not([style*="background"]),
  #page-content [style*="color:#008000"]:not([style*="background"]),
  #page-content [style*="color: #008000"]:not([style*="background"]) {
    color: var(--scpru-lift-green) !important;
  }

  #page-content [style*="color:purple"]:not([style*="background"]),
  #page-content [style*="color: purple"]:not([style*="background"]),
  #page-content [style*="color:indigo"]:not([style*="background"]),
  #page-content [style*="color: indigo"]:not([style*="background"]),
  #page-content [style*="color:#800080"]:not([style*="background"]),
  #page-content [style*="color: #800080"]:not([style*="background"]) {
    color: var(--scpru-lift-purple) !important;
  }

  #page-content [style*="color:maroon"]:not([style*="background"]),
  #page-content [style*="color: maroon"]:not([style*="background"]),
  #page-content [style*="color:darkred"]:not([style*="background"]),
  #page-content [style*="color: darkred"]:not([style*="background"]),
  #page-content [style*="color:#800000"]:not([style*="background"]),
  #page-content [style*="color: #800000"]:not([style*="background"]),
  #page-content [style*="color:#990000"]:not([style*="background"]),
  #page-content [style*="color: #990000"]:not([style*="background"]) {
    color: var(--scpru-lift-maroon) !important;
  }

  /* Pure red lands at 4.46:1 — a hair under AA. Softened just enough to pass
     while staying unmistakably the same red. */
  #page-content [style*="color:red"]:not([style*="background"]),
  #page-content [style*="color: red"]:not([style*="background"]),
  #page-content [style*="color:#ff0000"]:not([style*="background"]),
  #page-content [style*="color: #ff0000"]:not([style*="background"]) {
    color: var(--scpru-lift-red) !important;
  }

  #page-content [style*="color:brown"]:not([style*="background"]),
  #page-content [style*="color: brown"]:not([style*="background"]) {
    color: var(--scpru-lift-brown) !important;
  }

  #page-content [style*="color:teal"]:not([style*="background"]),
  #page-content [style*="color: teal"]:not([style*="background"]),
  #page-content [style*="color:#008080"]:not([style*="background"]),
  #page-content [style*="color: #008080"]:not([style*="background"]) {
    color: var(--scpru-lift-teal) !important;
  }

  /* The branch's own title and link crimsons. Authors paste them into
     style="color:…" on fake page titles and section heads, where they are
     near-black on a dark page. */
  #page-content [style*="color:#901"]:not([style*="background"]),
  #page-content [style*="color: #901"]:not([style*="background"]),
  #page-content [style*="color:#b01"]:not([style*="background"]),
  #page-content [style*="color: #b01"]:not([style*="background"]),
  #page-content [style*="color:#a01"]:not([style*="background"]),
  #page-content [style*="color: #a01"]:not([style*="background"]),
  #page-content [style*="color:#700"]:not([style*="background"]),
  #page-content [style*="color: #700"]:not([style*="background"]),
  #page-content [style*="color:#600"]:not([style*="background"]),
  #page-content [style*="color: #600"]:not([style*="background"]) {
    color: var(--scpru-lift-maroon) !important;
  }

  /* ============================================================
     FOOTER / LICENSE / NAVI
     ============================================================ */

  #container-wrap #footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
    border-top: 1px solid #262c33;
  }

  #footer a,
  #license-area a,
  .license-area a {
    color: #c4cdd6 !important;
  }

  #footer a:hover,
  #license-area a:hover,
  .license-area a:hover {
    color: #ff8f97 !important;
  }

  #container-wrap #license-area,
  .license-area {
    background-color: #0d1117 !important;
    color: #8b949e !important;
  }

  #navi-bar {
    background-color: #0d1117 !important;
    border-bottom-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  #navi-bar a,
  #navi-bar .action-buttons,
  #navi-bar .action-buttons a,
  #navi-bar .join,
  #navi-bar .random-site {
    color: #8ab4d8 !important;
  }

  #navi-bar .new-site input.empty {
    color: #8b949e !important;
  }

  #footer-bar {
    border-top-color: #262c33 !important;
  }

  /* Wikidot's own house ad slot, which punches a white hole in the page */
  #house-ad-1 {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  #house-ad-1 .close {
    background-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  .self-ads {
    border-color: #2d333b !important;
  }

  /* ============================================================
     SCROLLBAR
     ============================================================ */

  ::-webkit-scrollbar {
    border-color: rgba(255, 255, 255, .08) !important;
  }

  ::-webkit-scrollbar-track {
    background-color: #0d1117 !important;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #3a4048 !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background-color: #4a5058 !important;
  }

  /* ============================================================
     INTERWIKI FRAME (other-languages box)
     ============================================================ */

  #interwiki body,
  body#interwiki {
    background-color: transparent !important;
  }

  iframe.scpnet-interwiki-frame {
    background-color: #14181d !important;
  }

  #interwiki .menu-item a {
    color: #e8626e !important;
  }
}
